def is_representable(n, c1, c2):
    """Checks if n can be represented as c1*A + c2*B where A, B >= 0."""
    for A in range(n // c1 + 1):
        remainder = n - c1 * A
        if remainder >= 0 and remainder % c2 == 0:
            return True
    return False

N_max = 189
c1 = 11
c2 = 20
count_unrepresentable = 0

for n in range(1, N_max + 1):
    if not is_representable(n, c1, c2):
        count_unrepresentable += 1

print(f"The total count of integers between 1 and {N_max} that CANNOT be represented is: {count_unrepresentable}")
